import json
from collections import defaultdict

def get_neighbors(r, c, rows, cols):
    """Get valid neighbors (up, down, left, right)"""
    neighbors = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            neighbors.append((nr, nc))
    return neighbors

def find_connected_components(grid):
    """Find all connected components of non-2 cells (assuming 2 is the common color)"""
    rows, cols = len(grid), len(grid[0])

    # For each color, find connected components
    all_cells = set()
    for r in range(rows):
        for c in range(cols):
            all_cells.add((r, c))

    # Keep track of visited cells for each color
    visited = defaultdict(set)
    components = defaultdict(list)

    for r in range(rows):
        for c in range(cols):
            cell = grid[r][c]
            if cell in [0, 2]:  # Skip background/empty
                continue

    for key, value in visited.items():
        print(f"Visited for color {key}: {len(value)} cells")

def find_components_of_color(grid, color):
    """Find all connected components of a specific color"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                # BFS to find all connected cells
                component = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for nr, nc in get_neighbors(cr, cc, rows, cols):
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                            stack.append((nr, nc))
                components.append(component)

    return components

